def binary_search(arr: list[int], target: int, lo: int, hi: int) -> int:
    if lo > hi:                    # base case 1: not found
        return -1
    mid = (lo + hi) // 2
    if arr[mid] == target:         # base case 2: found
        return mid
    elif arr[mid] < target:
        return binary_search(arr, target, mid + 1, hi)
    else:
        return binary_search(arr, target, lo, mid - 1)

def sum_list(nums: list[int]) -> int:
    if not nums:              # base case: empty list sums to 0
        return 0
    # recursive case: first element + sum of the rest
    # len(nums[1:]) < len(nums), so we always make progress
    return nums[0] + sum_list(nums[1:])

# Recursive Fibonacci — clean but O(2^n) without memoization
def fib_recursive(n: int) -> int:
    if n <= 1: return n
    return fib_recursive(n - 1) + fib_recursive(n - 2)

# Iterative Fibonacci — O(n) time, O(1) space, no stack risk
def fib_iterative(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def merge_sort(arr: list[int]) -> list[int]:
    if len(arr) <= 1:             # base case
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])  # conquer left half
    right = merge_sort(arr[mid:]) # conquer right half
    return merge(left, right)     # combine

def merge(left: list[int], right: list[int]) -> list[int]:
    result, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i]); i += 1
        else:
            result.append(right[j]); j += 1
    return result + left[i:] + right[j:]

def is_even(n: int) -> bool:
    if n == 0:
        return True
    return is_odd(n - 1)   # delegate to partner

def is_odd(n: int) -> bool:
    if n == 0:
        return False
    return is_even(n - 1)  # delegate back

print(is_even(4))  # True
print(is_odd(7))   # True

from functools import lru_cache

# Without memoization: O(2^n) — recomputes fib(k) many times
def fib_slow(n: int) -> int:
    if n <= 1: return n
    return fib_slow(n - 1) + fib_slow(n - 2)

# With lru_cache: O(n) time, O(n) space — each subproblem computed once
@lru_cache(maxsize=None)
def fib(n: int) -> int:
    if n <= 1: return n
    return fib(n - 1) + fib(n - 2)

print(fib(100))  # 354224848179261915075 — instant
print(fib.cache_info())  # CacheInfo(hits=98, misses=101, ...)

