# Iterative DFS — same traversal order, no stack limit risk
def dfs_iterative(root) -> None:
    if root is None:
        return
    stack = [root]             # explicit stack
    while stack:
        node = stack.pop()     # LIFO: mirrors recursive call order
        print(node.val)
        # Push right first so left is processed first (pre-order)
        if node.right:
            stack.append(node.right)
        if node.left:
